import React, { useState } from 'react';
import StatsStep from './StatsStep';
import DetailsStep from './DetailsStep';
import './CharacterSheet.css';

const CharacterSheet = () => {
    const [currentStep, setCurrentStep] = useState(1);
    const [character, setCharacter] = useState({
        name: '', charClass: '', level: 1, species: '', playerName: '', expPoints: 0,
        stats: { Strength: 10, Dexterity: 10, Constitution: 10, Intelligence: 10, Wisdom: 10, Charisma: 10 },
        proficiencies: {}, skillOverrides: {},
        armorClass: 10, currentHp: 10, maxHp: 10, speed: 30,
        initiativeOverride: '', weapons: []
    });

    // --- HESAPLAMA MANTIKLARI ---
    const calculateModifier = (score) => Math.floor((score - 10) / 2);
    const getProficiencyBonus = (level) => Math.ceil(level / 4) + 1;
    const profBonus = getProficiencyBonus(character.level);

    const getSkillBonusValue = (statName, skillName) => {
        const key = `${statName}-${skillName}`;
        const modifier = calculateModifier(character.stats[statName]);
        return modifier + (character.proficiencies[key] ? profBonus : 0);
    };

    // --- HANDLERS ---
    const handleStatIncrease = (stat) => setCharacter(p => ({...p, stats: {...p.stats, [stat]: Math.min(30, p.stats[stat] + 1)}}));
    const handleStatDecrease = (stat) => setCharacter(p => ({...p, stats: {...p.stats, [stat]: Math.max(1, p.stats[stat] - 1)}}));
    const toggleProficiency = (stat, skill) => {
        const key = `${stat}-${skill}`;
        setCharacter(p => ({...p, proficiencies: {...p.proficiencies, [key]: !p.proficiencies[key]}}));
    };

    return (
        <div className="sheet-bg">
            <div className="sheet-container">
                {/* Header Kısmı Buraya Gelecek (Senin mevcut Header kodun) */}

                {currentStep === 1 ? (
                    <StatsStep 
                        character={character} 
                        setCharacter={setCharacter} 
                        calculateModifier={calculateModifier}
                        profBonus={profBonus}
                        handleStatIncrease={handleStatIncrease}
                        handleStatDecrease={handleStatDecrease}
                        toggleProficiency={toggleProficiency}
                        getCalculatedSkillBonus={(s, sk) => getSkillBonusValue(s, sk)}
                        displayInitiative={calculateModifier(character.stats.Dexterity)}
                        passivePerception={10 + getSkillBonusValue('Wisdom', 'Perception')}
                        passiveInsight={10 + getSkillBonusValue('Wisdom', 'Insight')}
                    />
                ) : (
                    <DetailsStep 
                        character={character}
                        handleWeaponChange={(id, f, v) => setCharacter(p => ({...p, weapons: p.weapons.map(w => w.id === id ? {...w, [f]: v} : w)}))}
                        handleRemoveWeapon={(id) => setCharacter(p => ({...p, weapons: p.weapons.filter(w => w.id !== id)}))}
                        handleAddWeapon={() => setCharacter(p => ({...p, weapons: [...p.weapons, {id: Date.now(), name: '', stat: 'Strength', damageDice: ''}]}))}
                        calculateModifier={calculateModifier}
                        profBonus={profBonus}
                    />
                )}

                <div className="sheet-actions">
                    <button onClick={() => setCurrentStep(currentStep === 1 ? 2 : 1)}>
                        {currentStep === 1 ? "NEXT: DETAILS ➔" : "← BACK TO STATS"}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default CharacterSheet;
